def record_existing_decisions(apps, schema_editor):
    """Say truthfully who decided what, for rows written before this existed.

    Before the type detector, the only way a document's type could be
    anything but GENERAL was a person choosing it - so every such document
    is "user", and stays out of the detector's reach. GENERAL ones are the
    untouched default.

    Every classification verdict on record came from a layout classifier
    (the column default), and each one labelled "unknown" was an abstention:
    that reserved label is what the classifiers stored when they declined.
    """
    Document = apps.get_model("documents", "Document")
    ClassificationResult = apps.get_model("documents", "ClassificationResult")

    Document.objects.exclude(document_type="GENERAL").update(
        document_type_source="user"
    )
    ClassificationResult.objects.filter(predicted_label="unknown").update(
        abstained=True
    )


